<template>
  <div ref="screen" class="data-screen" :class="{ 'motion-paused': !motion }">
    <div class="screen-ambient" aria-hidden="true" />
    <header class="screen-header">
      <div class="clock-block"><span class="live-dot" />{{ clock }}<small>{{ demo ? '浏览器模拟演示' : '实时运营监测' }}<b>ENERGY NETWORK / CONTROL CENTER</b></small></div>
      <div class="screen-title"><span>YUNENG · INTELLIGENT CHARGING</span><h1>驭能智充运营数据中心</h1><div class="title-beam" /></div>
      <div class="screen-actions"><button :aria-pressed="!motion" @click="motion=!motion"><i :class="motion ? 'el-icon-video-pause' : 'el-icon-video-play'" />{{ motion ? '暂停动效' : '开启动效' }}</button><button @click="toggleFullscreen"><i class="el-icon-full-screen" />浏览器全屏</button><button aria-label="返回仪表盘" @click="back">返回仪表盘 <i class="el-icon-right" /></button></div>
    </header>
    <div class="screen-meta"><span><i class="el-icon-position" /> {{ scopeLabel }}</span><span>{{ updatedAt ? '数据更新 ' + updatedAt : '正在读取数据' }}<i class="meta-divider" />60 秒刷新 <button :disabled="loading" @click="refreshOverview">{{ loading ? '同步中…' : '立即刷新' }}</button></span></div>
    <scope-selector :scope="scope" :operators="operators" :stations="stationOptions" dark @change="changeScope" />
    <div v-if="failures.length" class="screen-warning" role="alert">{{ failures.join('；') }}</div>
    <div class="screen-metrics"><div v-for="(card,i) in cards" :key="card.label" class="metric-tile"><span class="metric-index">0{{ i+1 }} / {{ card.english }}</span><div class="metric-body"><i :class="card.icon" /><div><span class="metric-label">{{ card.label }}</span><strong><animated-metric :value="card.value" :digits="card.digits || 0" :motion="motion" /><small>{{ card.unit }}</small></strong></div></div><div class="metric-track"><b /></div></div></div>
    <main class="screen-grid">
      <section class="screen-panel status-panel"><div class="panel-head"><h2>设备运行态势</h2><span>DEVICE STATUS</span></div><div class="status-chart"><overview-chart kind="status" :summary="summary" dark :motion="motion" /></div><div class="status-numbers"><div><i />在线 <b>{{ metric(summary.onLine) }}</b></div><div><i />离线 <b>{{ metric(summary.offLine) }}</b></div></div><div class="online-rate"><span>设备在线率</span><b>{{ onlineRate }}<small v-if="onlineRate!=='—'">%</small></b><div><i :style="{width:(onlineRate==='—'?0:onlineRate)+'%'}" /></div></div></section>
      <section class="screen-panel atlas-panel"><div class="panel-head"><h2>全国站点分布</h2><span>CHARGING NETWORK</span><b class="panel-badge">{{ metric(stationTotal) }} 站点</b></div><atlas-scene :stations="stations" :motion="motion" /><div class="atlas-caption"><span><i class="live-dot" />{{ scope.stationId ? '单站点视图' : '当前范围地理分布' }}</span><span>省级汇总 / 精确坐标分层展示</span></div></section>
      <section class="screen-panel alarm-panel"><div class="panel-head"><h2>最新设备告警</h2><span>ALARM EVENTS</span><b class="alarm-live" /></div><div v-if="!canFault" class="screen-empty">当前账号无告警查看权限</div><div v-for="alarm in alarms" :key="alarm.id" class="screen-alarm"><span class="alarm-badge">{{ alarm.priority==='HIGH'?'紧急':'告警' }}</span><div><strong>{{ alarm.description }}</strong><small>{{ alarm.pileId }}<time>{{ shortTime(alarm.occurredAt || alarm.receivedAt) }}</time></small></div></div><div v-if="canFault&&!alarms.length" class="screen-empty"><i class="el-icon-circle-check" />{{ loading ? '正在同步告警' : '当前范围暂无告警记录' }}</div><div class="alarm-footer"><span>处理中工单 <b>{{ metric(faultSummary.active) }}</b></span><span>已关闭 <b>{{ metric(faultSummary.closed) }}</b></span></div></section>
      <section class="screen-panel scope-panel"><div class="panel-head"><h2>{{ selectedStation ? '站点详情' : '运营概况' }}</h2><span>SCOPE OVERVIEW</span></div><h3>{{ selectedStation ? selectedStation.stationName : scope.root&&!scope.tenantId ? '全平台运营总览' : scopeLabel.split(' / ')[0] }}</h3><p>{{ selectedStation ? selectedStation.address || '地址待录入' : '当前筛选范围的累计经营数据' }}</p><div class="scope-stats"><div><span>累计充电次数</span><strong>{{ metric(summary.chargeTimes) }}<small> 次</small></strong></div><div><span>累计退款</span><strong>{{ metric(summary.reSales,2) }}<small> 元</small></strong></div></div><div class="scope-note"><i class="el-icon-lock" />{{ selectedStation ? '站点 #' + selectedStation.stationId : '按当前账号权限汇总' }}</div></section>
      <section class="screen-panel trend-panel"><div class="panel-head"><h2>近 30 天净收入趋势</h2><span>REVENUE TREND</span><b class="trend-key">净收入 / 元</b></div><overview-chart :data="trend" dark :motion="motion" /><span class="trend-note">总收益减退款 · 按订单创建日期汇总</span></section>
      <section class="screen-panel ranking-panel"><div class="panel-head"><h2>站点收入排行</h2><span>STATION RANKING</span></div><div class="ranking-heading"><span>站点名称</span><span>净收入 / 元</span></div><div class="rank-list"><button v-for="(item,i) in ranking" :key="item.stationId" class="rank-row" @click="changeScope({tenantId:scope.tenantId,stationId:item.stationId})"><b>{{ String(i+1).padStart(2,'0') }}</b><div><span>{{ item.name }}</span><div class="rank-track"><i :style="{width:rankWidth(item.revenue)+'%'}" /></div></div><strong>{{ metric(item.revenue,2) }}</strong></button></div><div v-if="!ranking.length" class="screen-empty">{{ loading ? '正在同步排行' : '当前范围暂无站点订单' }}</div></section>
    </main>
    <footer class="screen-footer"><span><i class="live-dot" />{{ demo ? 'DEMO · 浏览器模拟数据' : '已连接运营数据服务' }}</span><span>YUNENG ENERGY CLOUD<span class="footer-slash"> / </span>智能充电 · 数字运营</span><span>{{ motion ? '动态场景已开启' : '动态场景已暂停' }}</span></footer>
  </div>
</template>
<script>
import screenfull from 'screenfull'
import overview from './data'
import ScopeSelector from './ScopeSelector'
import OverviewChart from './OverviewChart'
import AtlasScene from './AtlasScene'
import AnimatedMetric from './AnimatedMetric'
export default {
  name: 'OperationsScreen',
  components: { ScopeSelector, OverviewChart, AtlasScene, AnimatedMetric },
  mixins: [overview],
  data() { return { clock: '', demo: process.env.VUE_APP_DEMO === 'true', motion: !matchMedia('(prefers-reduced-motion: reduce)').matches } },
  computed: {
    onlineRate() { return this.summary.totalNumbers > 0 ? (Number(this.summary.onLine) / Number(this.summary.totalNumbers) * 100).toFixed(1) : '—' },
    cards() {
      return [
        { label: '接入站点总数', value: this.stationTotal, unit: '个', icon: 'el-icon-location-outline', english: 'STATIONS' },
        { label: '联网设备总数', value: this.summary.totalNumbers, unit: '台', icon: 'el-icon-cpu', english: 'DEVICES' },
        { label: '累计实际收益', value: this.summary.realSales, digits: 2, unit: '元', icon: 'el-icon-wallet', english: 'NET REVENUE' },
        { label: '累计充电电量', value: this.summary.consumePower, digits: 2, unit: 'kWh', icon: 'el-icon-lightning', english: 'ENERGY' }
      ]
    }
  },
  mounted() { this.refreshOverview(); this.tick(); this.clockTimer = setInterval(() => { if (!document.hidden) this.tick() }, 1000); this.refreshTimer = setInterval(() => { if (!document.hidden && !this.loading) this.refreshOverview() }, 60000) },
  beforeDestroy() { clearInterval(this.clockTimer); clearInterval(this.refreshTimer); if (screenfull.isEnabled && screenfull.isFullscreen) screenfull.exit().catch(() => {}) },
  methods: {
    tick() { this.clock = new Date().toLocaleString('zh-CN', { hour12: false }) },
    shortTime(value) { return String(value || '').replace('T', ' ').slice(5, 19) },
    rankWidth(value) { const max = Math.max(0, ...this.ranking.map(r => Number(r.revenue))); return max > 0 ? Math.max(0, Number(value)) / max * 100 : 0 },
    async toggleFullscreen() { if (!screenfull.isEnabled) return this.$message.info('当前浏览器暂不支持全屏，可使用 F11'); try { await screenfull.toggle(this.$refs.screen) } catch (error) { this.$message.info('可使用浏览器 F11 进入全屏') } },
    async back() { if (screenfull.isEnabled && screenfull.isFullscreen) await screenfull.exit().catch(() => {}); this.$router.push({ path: '/index', query: this.$route.query }) }
  }
}
</script>
